// Builds .pi/APPEND_SYSTEM.md from the docs Claude Code used to @import in
// CLAUDE.md. Pi has no import syntax for context files, so the only way to keep
// those constraints always-on is to append them to the system prompt.
//
//   node tools/build-append-system.mjs          # write
//   node tools/build-append-system.mjs --check  # exit 1 if stale
//
// Edit the SOURCES, never the generated file.

import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const out = path.join(root, ".pi", "APPEND_SYSTEM.md");

// Order matters: structure first, then the rules that constrain edits, then the
// standards those rules defer to, then the engine pin the standards assume.
const SOURCES = [
  [".pi/docs/directory-structure.md", "Project structure"],
  [".pi/docs/coordination-rules.md", "Coordination rules"],
  [".pi/docs/coding-standards.md", "Coding standards"],
  ["docs/engine-reference/godot/VERSION.md", "Engine version reference"],
];

const header = `# Studio constraints (always on)

Generated by \`tools/build-append-system.mjs\` from the docs \`CLAUDE.md\` used to
\`@import\`. Pi has no import syntax, so these are appended to the system prompt
instead. Edit the sources, not this file.
`;

let body = header;
for (const [rel, title] of SOURCES) {
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) {
    console.error(`missing source: ${rel}`);
    process.exit(1);
  }
  const text = fs.readFileSync(abs, "utf8").replace(/^\uFEFF/, "").trimEnd();
  // Demote the source's own H1 so the sections sit under one document.
  const demoted = text.replace(/^# /m, "## ");
  body += `\n\n<!-- source: ${rel} -->\n## ${title} · \`${rel}\`\n\n${demoted}\n`;
}

if (process.argv.includes("--check")) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, "utf8") : "";
  if (current !== body) {
    console.error("stale: run node tools/build-append-system.mjs");
    process.exit(1);
  }
  console.log("APPEND_SYSTEM.md is up to date");
  process.exit(0);
}

fs.writeFileSync(out, body);
console.log(`wrote ${path.relative(root, out)} (${body.length} bytes, ${SOURCES.length} sources)`);
